import{_ as a,b as e,o as r,a8 as t}from"./chunks/framework.BEMRIPir.js";const u=JSON.parse('{"title":"异步编程的实现方式","description":"","frontmatter":{},"headers":[],"relativePath":"material/endorsement/js/async/async-programming-implementation.md","filePath":"material/endorsement/js/async/async-programming-implementation.md"}'),n={name:"material/endorsement/js/async/async-programming-implementation.md"},o=t('<h1 id="异步编程的实现方式" tabindex="-1">异步编程的实现方式 <a class="header-anchor" href="#异步编程的实现方式" aria-label="Permalink to &quot;异步编程的实现方式&quot;">​</a></h1><h2 id="回调函数" tabindex="-1">回调函数 <a class="header-anchor" href="#回调函数" aria-label="Permalink to &quot;回调函数&quot;">​</a></h2><p>回调是一个最基本的异步编程方式，使用它有一个缺点：如果多个回调函数发生嵌套行为，则会造成回调函数地狱，不利于代码的维护</p><h2 id="promise" tabindex="-1"><a href="./promise.html">promise</a> <a class="header-anchor" href="#promise" aria-label="Permalink to &quot;[promise](./promise.md)&quot;">​</a></h2><p>使用 promise 的方式可以将潜逃的回调函数作为链式调用，但多个链式调用可能会造成代码语义不明</p><h2 id="generator" tabindex="-1">generator <a class="header-anchor" href="#generator" aria-label="Permalink to &quot;generator&quot;">​</a></h2><ul><li>generator 可以在函数执行的过程中，将函数的执行权转移出去，在函数外部还可以将执行权转移回来</li><li>当遇到异步函数执行时，将函数执行权转移出去，当异步函数执行完毕后再将执行权转移回来</li><li>因此在 generator 内部对于异步操作的方式，可以用同步的顺序来书写</li><li>使用时最大的问题是何时将函数的控制权转移回来，所以需要一个自动执行 generator 的机制</li></ul><h2 id="async-函数" tabindex="-1">async 函数 <a class="header-anchor" href="#async-函数" aria-label="Permalink to &quot;async 函数&quot;">​</a></h2><p>async 函数是 generator 函数 + 自动执行器 实现的语法糖。当函数内部执行到一个 await 语句时，会等待异步行为执行后继续向下执行，因此可以将异步逻辑转化为同步顺序来书写。</p><h2 id="事件监听" tabindex="-1">事件监听 <a class="header-anchor" href="#事件监听" aria-label="Permalink to &quot;事件监听&quot;">​</a></h2><h2 id="发布订阅模式-观察者模式" tabindex="-1">发布订阅模式/观察者模式 <a class="header-anchor" href="#发布订阅模式-观察者模式" aria-label="Permalink to &quot;发布订阅模式/观察者模式&quot;">​</a></h2>',11),i=[o];function s(l,m,c,h,d,p){return r(),e("div",null,i)}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
